"""Regenerate the eleven skill entrypoints and self-contained repository launchers."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
skills = {
"copycat": ("Reconstruct an Indian disclosed equity sleeve from fund holdings or valued investor disclosures; compare snapshots.", "copycat", "Use NSE/BSE shareholding disclosures or an AMC's published fund portfolio. Read ../../docs/sources.md and ../../docs/schemas.md. Import normalized rows with source URLs, snapshot date and market_value_inr or portfolio_weight_pct. Issuer ownership percentages cannot be treated as portfolio weights. Never claim a complete celebrity investor portfolio from thresholded issuer disclosures. Compare quantities only after checking splits, bonuses and mergers.\n\nCommands: `copycat INPUT --top 5` writes targets; `copycat INPUT --previous OLD` compares quantities. The selected disclosed equity sleeve is renormalized; cash and omitted assets are not recovered."),
"news": ("Monitor public Indian company announcements and India-focused news for a watchlist.", "news", "Read ../../docs/sources.md. Use `news NSE:INFY NSE:TCS` for RSS and `filings announcements NSE:INFY` for exchange metadata. `news --input FILE` accepts a saved normalized feed. Verify material claims against the original exchange filing and separate publication time, event date and fetch time. A headline is not an automatic trade signal. Errors and unknown dates must remain visible. Run once per requested poll; no scheduler is installed."),
"budget": ("Size INR whole-share delivery allocations and fully funded long intraday trades with stop-based risk limits.", "budget", "Read ../../docs/schemas.md. Confirm the user's capital and risk limits; examples are synthetic. `budget` uses targets.json, prices.json and config.json and writes orders.json. For existing holdings use rebalance. `intraday NSE:INFY --entry 1500 --stop 1480` sizes a long MIS proposal with round-trip estimated charges. No fractional shares, notional tickets or assumed 5x leverage. Stop loss is planning metadata only; no linked exit is placed. Send all proposals through risk."),
"disclosures": ("Track public Indian promoter and insider disclosures, including transaction and disclosure dates.", "disclosures", "This replaces the upstream US politician tracker. It does not track Indian MPs' stock trades. Read ../../docs/sources.md and ../../docs/schemas.md. `filings insider NSE:INFY` fetches public raw metadata. Normalize exchange CSV or attached filings to the disclosure schema, preserve source_url, transaction_date, disclosed_at and transaction_type, then `disclosures INPUT`. The command records seen IDs. Keep gifts, pledges, ESOPs and inter-se transfers distinct from market purchases. Do not infer unpublished holdings or treat reported activity as inside information."),
"analyst": ("Analyze Indian quarterly financial results with INR/lakh/crore unit conversion and comparable reporting periods.", "analyst", "Use `filings results NSE:INFY` to discover filings; read original results and normalize them to ../../docs/schemas.md. `analyst INPUT` writes metrics.json with revenue, PAT, net margin, YoY revenue growth and four-quarter EPS. Keep standalone and consolidated series separate. Accept individual quarters only; derive Q4 from audited year minus nine months only if scope and restatements match, documenting the derivation. Never label cumulative YTD as a quarter. Review banking/NBFC metrics separately; EPS must share a consistent corporate-action basis."),
"screener": ("Screen and rank Indian equity research metrics using user-defined numerical rules.", "screen", "Use `screen --input METRICS --rules RULES` or workspace metrics.json/rules.json. Read ../../docs/schemas.md. Missing rule metrics fail explicitly. Explain failed rules and missing ranking metrics. Compare one reporting basis and period per company; do not rank duplicate standalone/consolidated rows together. Screen results are candidates, not orders. For intraday candidates also review liquidity, spread, surveillance, broker eligibility and current instrument metadata."),
"risk": ("Check INR equity proposals against current account, quote, session, instrument and intraday risk constraints.", "risk", "Read ../../docs/schemas.md and ../../docs/operations.md. Run `risk`; exit 1 indicates blocked proposals, 2 invalid inputs. Inputs need a reconciled dated account, timestamped quotes, same-day instrument metadata and verified calendar. Explain every BLOCK; do not silently loosen limits, relabel delayed quotes as live or substitute cost basis for a current valuation. Checks include ticks/circuits, whole shares, fees, cumulative cash/position exposure, duplicate orders, daily loss and entry cutoff. No sale is assumed filled to finance a buy. Every changed order, account or data input invalidates prior approval."),
"broker": ("Connect Kite, Dhan and Groww for account/data reads, preview tickets and simulate approved local paper fills.", "broker", "Read ../../docs/operations.md and ../../docs/brokers.md. Use `connections connect kite` in the user's local terminal for hidden credential entry, then `connections status/sync/report kite`. Dhan and Groww use the same interface. Never request credentials in chat. Snapshots retain broker financial semantics and do not replace paper accounts or FIFO lots. `connections quotes kite NSE:INFY --publish` can replace paper quotes only after all symbols succeed; preserve timestamps. `connections preview PROVIDER` is FORMAT_ONLY, not risk approval. This implementation cannot submit live orders. `broker show` rechecks risk and renders the exact LIMIT DAY Kite-compatible manual payload. The user acknowledgement is `YES FULL_FINGERPRINT` for one order; pass the actual user response to `broker approve --index N --reply TEXT`. Never manufacture a reply from broad permission to build software. `broker fill --index N --fill-price PRICE` records a synthetic fill exactly at the approved limit; it is not evidence of market execution. Inputs and risk must still match; approvals expire and cannot replay. Stop-loss metadata is not a protective order. Live actions remain with the user in their broker application."),
"tax": ("Compute Indian equity FIFO realized gains, financial-year totals and delivery loss candidates.", "tax", "Read ../../docs/tax.md and ../../docs/schemas.md. `tax report --input LEDGER --fy 2026-27` requires all opening purchases and fills, with demat-account identity and actual delivery classification. `tax harvest` lists estimated delivery loss candidates but creates no orders. Same-day non-delivery trades can be speculative business even if tagged CNC. Delivery shares are assumed capital assets for the report; frequent trading may need a different treatment. No US wash-sale window or HIFO selection is imported. Do not describe totals as final tax liability."),
"alerts": ("Check Indian equity price levels, CAS-aware market sessions and intraday exit reminders.", "alerts", "Use `quote NSE:INFY` for unofficial research data and `clock --cas yes` for session state; missing CAS eligibility returns UNKNOWN. `alerts` performs one poll of workspace alerts.json, rejecting stale quotes and storing once-per-IST-date deduplication. Read ../../docs/operations.md. The open alert means the first poll observing the continuous session, not a guaranteed opening-bell delivery. Reminders do not close positions. Calendar coverage is bounded; verify later circulars and special sessions before use. A scheduler is an external user-configured operation."),
"rebalance": ("Plan INR whole-share delivery portfolio rebalancing against capped target weights.", "rebalance", "Run `rebalance --band 5` after reconciling account holdings and quotes. Band is percentage points of total equity. It writes capped LIMIT proposals with drift details; it does not force fractional shares or spend unfilled sale proceeds. The plan includes exits of holdings omitted from the target, so explicitly show those exits. Intraday holdings must be closed/reconciled first. Sell first, record actual/paper fills, regenerate buys, rerun risk and obtain fresh per-ticket acknowledgement. Charges and caps can leave residual drift/cash.")
}
common = """
Use this skill only for the requested Indian-market task. Work from the repository root or run the bundled launcher by its absolute path. Python 3.10+ and the standard library are sufficient.

Run `python <skill-folder>/scripts/run.py --help` to see all commands. Global options `--workspace PATH`, `--now TIMESTAMP` and `--out PATH` precede the command. The graphical application exposes these services without terminal commands; see ../../docs/ui.md. The default CLI workspace is `trader/` under the working directory. `--now` is for explicit offline simulation only; omit for current checks. The launcher resolves the shared engine relative to this repository; keep the full repository together.

All trade plans are paper proposals. Free data can be delayed, blocked or incomplete. Keep source timestamps and evidence, distinguish observed data from inference, and never fill missing facts with invented values. See [sources](../../docs/sources.md), [schemas](../../docs/schemas.md), and [operations](../../docs/operations.md).
"""
paths = []
for name, (description, command, body) in skills.items():
    folder = ROOT / "skills" / ("india-trader-" + name)
    (folder / "scripts").mkdir(parents=True, exist_ok=True)
    (folder / "SKILL.md").write_text("---\nname: india-trader-" + name + "\ndescription: " + description + "\n---\n\n" + body + "\n" + common, encoding="utf-8")
    (folder / "scripts/run.py").write_text('"""Launch the shared India Trader CLI from any working directory."""\nfrom pathlib import Path\nimport sys\nsys.path.insert(0, str(Path(__file__).resolve().parents[3]))\nfrom india_trader.cli import main\nraise SystemExit(main())\n', encoding="utf-8")
    paths.append("./skills/india-trader-" + name)
plugin = ROOT / ".claude-plugin"
plugin.mkdir(exist_ok=True)
(plugin / "plugin.json").write_text(json.dumps({"name": "india-trader", "version": "1.2.0", "description": "Eleven Indian equity research, risk and paper trading skills", "license": "MIT", "skills": paths}, indent=2) + "\n")
(plugin / "marketplace.json").write_text(json.dumps({"name": "india-trader-local", "owner": {"name": "India Trader maintainers"}, "plugins": [{"name": "india-trader", "source": "./", "description": "Indian-market adaptation of trader-skill"}]}, indent=2) + "\n")
